export const binaryOpPredicates: opPredicates = new Map<TokenKind, (typ: Type) => boolean>([
  [TokenKind.Plus, allNumericOrString],
  [TokenKind.Minus, allNumeric],
  [TokenKind.Star, allNumeric],
  [TokenKind.Slash, allNumeric],
  [TokenKind.Percent, allInteger],

  [TokenKind.Amp, allInteger],
  [TokenKind.Or, allInteger],
  [TokenKind.Caret, allInteger],
  [TokenKind.BitClear, allInteger],

  [TokenKind.AndAnd, allBoolean],
  [TokenKind.OrOr, allBoolean],
]);

